const { google } = require('googleapis');
const fs = require('fs');

async function main() {
    // Load credentials
    const credentials = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json'));
    const tokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json'));

    const { client_id, client_secret } = credentials.installed;
    const account = tokens.accounts.default;

    // Create OAuth2 client
    const oauth2Client = new google.auth.OAuth2(
        client_id,
        client_secret,
        'http://localhost'
    );

    // Set credentials - try to generate a token URL with calendar scopes
    oauth2Client.setCredentials({
        refresh_token: account.refresh_token,
    });

    // Generate auth URL with proper scopes
    const authUrl = oauth2Client.generateAuthUrl({
        access_type: 'offline',
        scope: [
            'https://www.googleapis.com/auth/calendar',
            'https://www.googleapis.com/auth/calendar.events',
            'https://www.googleapis.com/auth/gmail.send',
            'https://www.googleapis.com/auth/gmail.modify',
        ],
    });
    console.log('Auth URL:', authUrl);

    // Try to use the refresh token to get a new access token
    try {
        const { credentials: newCreds } = await oauth2Client.refreshAccessToken();
        console.log('Refresh succeeded');
        console.log('Scope:', newCreds.scope);
        console.log('Token type:', newCreds.token_type);

        // Try Calendar API
        const calendar = google.calendar({ version: 'v3', auth: oauth2Client });
        const events = await calendar.events.list({
            calendarId: 'primary',
            timeMin: '2026-01-06T00:00:00Z',
            timeMax: '2026-01-10T00:00:00Z',
            singleEvents: true,
            orderBy: 'startTime',
        });

        console.log('Events:', JSON.stringify(events.data, null, 2));
    } catch (err) {
        console.error('Error:', err.message);

        // Maybe try with the access_token from the tokens file
        oauth2Client.setCredentials({
            access_token: account.access_token,
            refresh_token: account.refresh_token,
            expiry_date: account.expiry_date,
            scope: account.scope,
        });

        try {
            const calendar = google.calendar({ version: 'v3', auth: oauth2Client });
            const events = await calendar.events.list({
                calendarId: 'primary',
                timeMin: '2026-01-06T00:00:00Z',
                timeMax: '2026-01-10T00:00:00Z',
                singleEvents: true,
                orderBy: 'startTime',
            });
            console.log('Events (with stored token):', JSON.stringify(events.data, null, 2));
        } catch (err2) {
            console.error('Error 2:', err2.message);
        }
    }
}

main().catch(console.error);
